// Generated by `nelv` from .nelvrc.json capabilities. Change it with `nelv add`; module options go in
// ./platform.options.ts, app modules in ./modules.
import { approval } from '@elvine-sk/platform-approval'
import { audit } from '@elvine-sk/platform-audit'
import { auth, authConfigSchema } from '@elvine-sk/platform-auth'
import { authorization } from '@elvine-sk/platform-authorization'
import { dashboard } from '@elvine-sk/platform-dashboard'
import { files, filesConfigSchema } from '@elvine-sk/platform-files'
import { jobs, jobsConfigSchema } from '@elvine-sk/platform-jobs'
import { notifications } from '@elvine-sk/platform-notifications'
import { transfer } from '@elvine-sk/platform-transfer'
import { views } from '@elvine-sk/platform-views'
import { platformOptions } from './platform.options.ts'

export const APP_NAME = 'hr-fam'
export const APP_TITLE = 'HR-FAM'

/** Config schemas of the platform modules, merged into `loadConfig`. */
export const platformConfigSchema = {
  ...authConfigSchema,
  ...jobsConfigSchema,
  ...filesConfigSchema,
}

type OptionsOf<F extends (...args: any) => unknown> = Partial<NonNullable<Parameters<F>[0]>>

/** What `./platform.options.ts` may set, per platform module, typed by the installed packages. */
export interface PlatformOptions {
  audit?: OptionsOf<typeof audit>
  auth?: OptionsOf<typeof auth>
  authorization?: OptionsOf<typeof authorization>
  jobs?: OptionsOf<typeof jobs>
  notifications?: OptionsOf<typeof notifications>
  files?: OptionsOf<typeof files>
  approval?: OptionsOf<typeof approval>
}

/** Platform modules in registration order. */
export function platformModules() {
  return [
    audit(platformOptions.audit),
    auth({ appName: APP_TITLE, ...platformOptions.auth }),
    authorization(platformOptions.authorization),
    jobs(platformOptions.jobs),
    notifications(platformOptions.notifications),
    views(),
    dashboard(),
    files(platformOptions.files),
    approval(platformOptions.approval),
    transfer(),
  ]
}
